	private void toggleChecklist()
	{
		configManager.setConfiguration("farming-patch-advisor", "showChecklistOverlay",
			!config.showChecklistOverlay());
		updateChecklistButton();
	}

	private void updateChecklistButton()
	{
		boolean selected = config.showChecklistOverlay();
		checklistToggle.setSelected(selected);
		checklistToggle.setText(selected ? "Checklist ON" : "Checklist OFF");
		checklistToggle.setBackground(selected ? new Color(45, 110, 70) : ColorScheme.MEDIUM_GRAY_COLOR);
		checklistToggle.setForeground(Color.WHITE);
	}

	private static void styleButton(AbstractButton button)
	{
		button.setFocusPainted(false);
		button.setForeground(Color.WHITE);
		button.setBackground(ColorScheme.MEDIUM_GRAY_COLOR);
		button.setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createLineBorder(ColorScheme.BORDER_COLOR),
			BorderFactory.createEmptyBorder(6, 8, 6, 8)));
	}

	private static List<PatchTimer> takeMatchingTimers(List<PatchTimer> timers, FarmRunPatch patch)
	{
		List<PatchTimer> matching = new ArrayList<>();
		for (int i = timers.size() - 1; i >= 0; i--)
		{
			PatchTimer timer = timers.get(i);
			if (timer.getPatchType() == patch.getPatchType()
				&& PatchLocationCatalog.name(timer.getPatchLocation()).equals(patch.getLocation()))
			{
				matching.add(0, timers.remove(i));
			}
		}
		return matching;
	}

	private JPanel createUntrackedCard(int order, FarmRunPatch patch)
	{
		JPanel card = createCard(48, false, ColorScheme.MEDIUM_GRAY_COLOR);
		addLine(card, order + ". " + patch.getDisplayName(), Color.WHITE, true);
		addLine(card, patch.getPatchType().getDisplayName() + " - Not inspected", Color.GRAY, false);
		addResetMenu(card, patch);
		return card;
	}

	private JPanel createTrackedCard(int order, FarmRunPatch patch, List<PatchTimer> matchingTimers)
	{
		Instant now = Instant.now();
		Color cardStateColor = combinedStateColor(matchingTimers, now);
		boolean attention = !Color.WHITE.equals(cardStateColor);
		int height = 48 + matchingTimers.size() * 57;
		for (PatchTimer timer : matchingTimers)
		{
			if ((!timer.isPlantedTimer() && !timer.isDead() && !timer.isDiseased())
				|| timer.isDead() || timer.isDiseased())
			{
				height += 18;
			}
		}
		JPanel card = createCard(height, attention, cardStateColor);
		addLine(card, order + ". " + patch.getDisplayName(), cardStateColor, true);
		addLine(card, "Patch: " + patch.getPatchType().getDisplayName()
			+ (patch.getPatchCount() > 1 ? " (" + matchingTimers.size() + "/" + patch.getPatchCount() + " tracked)" : ""),
			Color.LIGHT_GRAY, false);
		int timerNumber = 1;
		for (PatchTimer timer : matchingTimers)
		{
			String prefix = matchingTimers.size() > 1 ? timerNumber++ + ". " : "";
			addLine(card, prefix + "Planted: " + timer.getCrop().getName(), Color.LIGHT_GRAY, false);
			addLine(card, (timer.isPlantedTimer() ? "Started: " : "Inspected: ") + CLOCK.format(timer.getPlantedAt()), Color.LIGHT_GRAY, false);
			if (!timer.isPlantedTimer() && !timer.isDead() && !timer.isDiseased() && !timer.isPicked())
			{
				addLine(card, "Stage: " + timer.getEstimatedStage(now) + "/" + timer.getTotalStages() + " (maximum estimate)", Color.LIGHT_GRAY, false);
			}
			boolean timerReady = !timer.isDead() && !timer.isDiseased() && !timer.isPicked()
				&& !now.isBefore(timer.getReadyAt());
			String remaining = timer.isDead() ? "DEAD" : timer.isDiseased() ? "DISEASED"
				: timer.isPicked() ? "PICKED"
				: timerReady ? "READY"
				: PatchTimerOverlay.formatRemaining(Duration.between(now, timer.getReadyAt()));
			addLine(card, "Time remaining: " + remaining,
				PatchTimerOverlay.stateColor(timer, now), true);
			String remedy = PatchRemedy.forTimer(timer);
			if (remedy != null)
			{
				addLine(card, "Remedy: " + remedy, Color.LIGHT_GRAY, false);
			}
		}
		addResetMenu(card, patch);
		return card;
	}

	private static Color combinedStateColor(List<PatchTimer> timers, Instant now)
	{
		Color color = Color.WHITE;
		for (PatchTimer timer : timers)
		{
			Color timerColor = PatchTimerOverlay.stateColor(timer, now);
			if (Color.RED.equals(timerColor))
			{
				return Color.RED;
			}
			if (Color.ORANGE.equals(timerColor))
			{
				color = Color.ORANGE;
			}
			else if (Color.GREEN.equals(timerColor) && Color.WHITE.equals(color))
			{
				color = Color.GREEN;
			}
		}
		return color;
	}

	private void addResetMenu(JPanel card, FarmRunPatch patch)
	{
		JPopupMenu menu = new JPopupMenu();
		JMenuItem reset = new JMenuItem("Reset " + patch.getDisplayName());
		reset.addActionListener(event -> timerManager.reset(patch.getLocation(), patch.getPatchType()));
		menu.add(reset);
		card.setComponentPopupMenu(menu);
		for (Component component : card.getComponents())
		{
			if (component instanceof JLabel)
			{
				((JLabel) component).setComponentPopupMenu(menu);
			}
		}
	}

	private static JPanel createCard(int height, boolean ready, Color readyColor)
	{
		JPanel card = new JPanel();
		card.setLayout(new BoxLayout(card, BoxLayout.Y_AXIS));
		card.setAlignmentX(Component.LEFT_ALIGNMENT);
		card.setPreferredSize(new Dimension(PANEL_WIDTH - 28, height));
		card.setMinimumSize(new Dimension(PANEL_WIDTH - 28, height));
		card.setMaximumSize(new Dimension(Integer.MAX_VALUE, height));
		card.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		card.setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createLineBorder(ready ? readyColor : ColorScheme.BORDER_COLOR),
			BorderFactory.createEmptyBorder(6, 8, 6, 8)));
		return card;
	}

	private static void addLine(JPanel card, String text, Color color, boolean bold)
	{
		JLabel label = new JLabel(text);
		label.setAlignmentX(Component.LEFT_ALIGNMENT);
		label.setHorizontalAlignment(JLabel.LEFT);
		label.setForeground(color);
		if (bold)
		{
			label.setFont(label.getFont().deriveFont(Font.BOLD));
		}
		card.add(label);
	}
}

package com.farmingpatchadvisor;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.FontMetrics;
import java.time.Duration;
import java.time.Instant;
import java.util.ArrayList;
import java.util.List;
import javax.inject.Inject;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

final class PatchTimerOverlay extends OverlayPanel
{
	private static final int MAX_CONTENT_WIDTH = 340;
	private final PatchTimerManager timerManager;
	private final FarmingPatchAdvisorConfig config;

	@Inject
	private PatchTimerOverlay(PatchTimerManager timerManager, FarmingPatchAdvisorConfig config)
	{
		this.timerManager = timerManager;
		this.config = config;
		setPosition(OverlayPosition.TOP_LEFT);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
		setPriority(PRIORITY_LOW);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.showTimerOverlay() || timerManager.getTimers().isEmpty())
		{
			return null;
		}

		Instant now = Instant.now();
		int contentWidth = graphics.getFontMetrics().stringWidth("Farming Patch Timers");
		panelComponent.getChildren().add(TitleComponent.builder()
			.text("Farming Patch Timers")
			.build());

		for (PatchTimer timer : timerManager.getTimers())
		{
			boolean ready = !timer.isDead() && !timer.isDiseased() && !timer.isPicked()
				&& !now.isBefore(timer.getReadyAt());
			WorldPoint location = timer.getPatchLocation();
			String patch = timer.getCrop().getName() + " - " + PatchLocationCatalog.name(location);
			if (!timer.isPlantedTimer() && !timer.isDead() && !timer.isDiseased())
			{
				patch += " " + timer.getEstimatedStage(now) + "/" + timer.getTotalStages();
			}
			String remaining = timer.isDead() ? "DEAD" : timer.isDiseased() ? "DISEASED"
				: timer.isPicked() ? "PICKED"
				: ready ? "READY" : formatRemaining(Duration.between(now, timer.getReadyAt()));
			FontMetrics metrics = graphics.getFontMetrics();
			Color stateColor = stateColor(timer, now);
			int combinedWidth = metrics.stringWidth(patch) + metrics.stringWidth(remaining) + 18;
			if (combinedWidth <= MAX_CONTENT_WIDTH)
			{
				contentWidth = Math.max(contentWidth, combinedWidth);
				panelComponent.getChildren().add(LineComponent.builder()
					.left(patch).right(remaining).leftColor(stateColor)
					.rightColor(stateColor).build());
			}
			else
			{
				for (String line : wrapText(patch, metrics, MAX_CONTENT_WIDTH))
				{
					contentWidth = Math.max(contentWidth, metrics.stringWidth(line));
					panelComponent.getChildren().add(LineComponent.builder()
						.left(line).leftColor(stateColor).build());
				}
				contentWidth = Math.max(contentWidth, metrics.stringWidth(remaining));
				panelComponent.getChildren().add(LineComponent.builder().right(remaining)
					.rightColor(stateColor).build());
			}
			String remedy = PatchRemedy.forTimer(timer);
			if (remedy != null)
			{
				String remedyText = "Remedy: " + remedy;
				for (String line : wrapText(remedyText, metrics, MAX_CONTENT_WIDTH))
				{
					contentWidth = Math.max(contentWidth, metrics.stringWidth(line));
					panelComponent.getChildren().add(LineComponent.builder()
						.left(line).leftColor(Color.LIGHT_GRAY).build());
				}
			}
		}
		panelComponent.setPreferredSize(new Dimension(contentWidth + 20, 0));

		return super.render(graphics);
	}

	static Color stateColor(PatchTimer timer, Instant now)
	{
		if (timer.isDead())
		{
			return Color.RED;
		}
		if (timer.isDiseased())
		{
			return Color.ORANGE;
		}
		if (timer.isPicked())
		{
			return Color.WHITE;
		}
		return now.isBefore(timer.getReadyAt()) ? Color.WHITE : Color.GREEN;
	}

	static List<String> wrapText(String text, FontMetrics metrics, int maximumWidth)
	{
		List<String> lines = new ArrayList<>();
		StringBuilder line = new StringBuilder();
		for (String word : text.split("\\s+"))
		{
			String candidate = line.length() == 0 ? word : line + " " + word;
			if (line.length() > 0 && metrics.stringWidth(candidate) > maximumWidth)
			{
				lines.add(line.toString());
				line.setLength(0);
			}
			if (line.length() > 0)
			{
				line.append(' ');
			}
			line.append(word);
		}
		if (line.length() > 0)
		{
			lines.add(line.toString());
		}
		return lines;
	}

	static String formatRemaining(Duration duration)
	{
		long seconds = Math.max(0, duration.getSeconds());
		long days = seconds / 86400;
		long hours = (seconds % 86400) / 3600;
		long minutes = (seconds % 3600) / 60;
		long secs = seconds % 60;
		if (days > 0)
		{
			return String.format("%dd %02d:%02d", days, hours, minutes);
		}
		if (hours > 0)
		{
			return String.format("%d:%02d:%02d", hours, minutes, secs);
		}
		return String.format("%02d:%02d", minutes, secs);
	}
}

package com.farmingpatchadvisor;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics;
import java.awt.Rectangle;
import javax.swing.JButton;
import javax.swing.JComponent;
import javax.swing.plaf.basic.BasicScrollBarUI;
import net.runelite.client.ui.ColorScheme;

final class NarrowScrollBarUI extends BasicScrollBarUI
{
	static final int WIDTH = 8;
	private static final Color TRACK_COLOR = ColorScheme.MEDIUM_GRAY_COLOR;
	private static final Color THUMB_COLOR = ColorScheme.LIGHT_GRAY_COLOR;

	@Override
	protected void paintTrack(Graphics graphics, JComponent component, Rectangle bounds)
	{
		graphics.setColor(TRACK_COLOR);
		graphics.fillRect(bounds.x, bounds.y, bounds.width, bounds.height);
	}

	@Override
	protected void paintThumb(Graphics graphics, JComponent component, Rectangle bounds)
	{
		if (!component.isEnabled() || bounds.isEmpty())
		{
			return;
		}
		graphics.setColor(THUMB_COLOR);
		graphics.fillRect(bounds.x + 1, bounds.y, Math.max(1, bounds.width - 2), bounds.height);
	}

	@Override
	protected Dimension getMinimumThumbSize()
	{
		return new Dimension(WIDTH - 2, 24);
	}

	@Override
	protected JButton createDecreaseButton(int orientation)
	{
		return createHiddenButton();
	}

	@Override
	protected JButton createIncreaseButton(int orientation)
	{
		return createHiddenButton();
	}

	private static JButton createHiddenButton()
	{
		JButton button = new JButton();
		Dimension size = new Dimension(0, 0);
		button.setPreferredSize(size);
		button.setMinimumSize(size);
		button.setMaximumSize(size);
		return button;
	}
}

package com.farmingpatchadvisor;

import javax.inject.Singleton;

@Singleton
final class FarmRunFilterState
{
	private FarmRunFilter selected = FarmRunFilter.ALL;

	synchronized FarmRunFilter getSelected()
	{
		return selected;
	}

	synchronized void setSelected(FarmRunFilter selected)
	{
		this.selected = selected == null ? FarmRunFilter.ALL : selected;
	}

	synchronized boolean includes(PatchType patchType)
	{
		return selected.includes(FarmRunType.forPatchType(patchType));
	}
}

