		private boolean watered;

		private Inspection(WorldPoint location, PatchType patchType, Crop crop, long startedAtMillis)
		{
			this.location = location;
			this.patchType = patchType;
			this.crop = crop;
			this.startedAtMillis = startedAtMillis;
