	HERB(FarmRunType.HERB),
	TREE(FarmRunType.TREE),
	FRUIT_TREE_CALQUAT(FarmRunType.FRUIT_TREE_CALQUAT),
	TREE_AND_FRUIT_TREE("Tree + Fruit Tree", EnumSet.of(FarmRunType.TREE, FarmRunType.FRUIT_TREE_CALQUAT)),
