package com.farmingpatchadvisor;

import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.FontID;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.JavaScriptCallback;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetType;
import net.runelite.client.plugins.bank.BankSearch;

@Singleton
final class BankChecklistFilter
{
	private static final int ACTIVE_COLOR = 0x46D37B;
	private static final int INACTIVE_COLOR = 0xFF981F;
	private static final int SIDE_RAIL_X = 1;
	private static final int SIDE_RAIL_WIDTH = 39;
	private static final int BUTTON_HEIGHT = 34;
	private static final int SCROLL_BUTTON_HEIGHT = 20;
	private static final int TAB_HEIGHT_WITH_MARGIN = 41;
	private static final int TAB_AREA_TOP = 61;
	private static final int BANK_BOTTOM_OFFSET = 39;
	private final Client client;
	private final BankSearch bankSearch;
	private final FarmingLoadout farmingLoadout;
	private final FarmingPatchAdvisorConfig config;
	private Widget button;
	private boolean active;

	@Inject
	private BankChecklistFilter(Client client, BankSearch bankSearch, FarmingLoadout farmingLoadout,
		FarmingPatchAdvisorConfig config)
	{
		this.client = client;
		this.bankSearch = bankSearch;
		this.farmingLoadout = farmingLoadout;
		this.config = config;
	}

	void addButton()
	{
		Widget bankRoot = client.getWidget(InterfaceID.Bankmain.UNIVERSE);
		Widget itemsContainer = client.getWidget(InterfaceID.Bankmain.ITEMS_CONTAINER);
		if (bankRoot == null || itemsContainer == null)
		{
			return;
		}
		if (button != null && containsChild(bankRoot, button))
		{
			repositionButton();
			return;
		}
		button = bankRoot.createChild(-1, WidgetType.TEXT);
		button.setOriginalWidth(SIDE_RAIL_WIDTH);
		button.setOriginalHeight(BUTTON_HEIGHT);
		button.setFontId(FontID.BOLD_12);
		button.setXTextAlignment(1);
		button.setYTextAlignment(1);
		button.setTextShadowed(true);
		button.setText("Farm<br>Run");
		button.setTextColor(active ? ACTIVE_COLOR : INACTIVE_COLOR);
		button.setAction(0, active ? "Show all bank items" : "Show farm-run items");
		button.setHasListener(true);
		button.setNoClickThrough(true);
		button.setOnOpListener((JavaScriptCallback) event -> toggle());
		repositionButton();
	}

	void repositionButton()
	{
		Widget itemsContainer = client.getWidget(InterfaceID.Bankmain.ITEMS_CONTAINER);
		if (button == null || itemsContainer == null)
		{
			return;
		}

		int lowerBoundary = itemsContainer.getHeight() - BANK_BOTTOM_OFFSET;
		Widget incinerator = client.getWidget(InterfaceID.Bankmain.INCINERATOR_TARGET);
		if (incinerator != null && !incinerator.isHidden())
		{
			lowerBoundary = Math.min(lowerBoundary, incinerator.getRelativeY());
		}

		int tabCount = Math.max(0,
			(lowerBoundary - TAB_AREA_TOP - SCROLL_BUTTON_HEIGHT) / TAB_HEIGHT_WITH_MARGIN);
		int downArrowY = TAB_AREA_TOP + tabCount * TAB_HEIGHT_WITH_MARGIN + 1;
		button.setOriginalX(itemsContainer.getRelativeX() + SIDE_RAIL_X);
		button.setOriginalY(itemsContainer.getRelativeY()
			+ Math.max(TAB_AREA_TOP, downArrowY - BUTTON_HEIGHT - 2));
		button.revalidate();
	}

	private static boolean containsChild(Widget parent, Widget expectedChild)
	{
		Widget[] children = parent.getChildren();
		if (children == null)
		{
			return false;
		}
		for (Widget child : children)
		{
			if (child == expectedChild)
			{
				return true;
			}
		}
		return false;
	}

	void removeButton()
	{
		if (button != null)
		{
			button.setHidden(true);
			button = null;
		}
		if (active)
		{
			active = false;
			bankSearch.layoutBank();
		}
	}

	void onBankClosed()
	{
		button = null;
		active = false;
	}

	void filterBankItem()
	{
		if (!active)
		{
			return;
		}
		int[] stack = client.getIntStack();
		int size = client.getIntStackSize();
		if (size < 2)
		{
			return;
		}
		int itemId = stack[size - 1];
		Set<Integer> checklistIds = farmingLoadout.bankChecklistItemIds(
			config.includeCompost(), config.checklistTools(), config.checklistPayments(),
			ChecklistPatch.selected(config));
		stack[size - 2] = checklistIds.contains(itemId) ? 1 : 0;
	}

	private void toggle()
	{
		active = !active;
		if (button != null)
		{
			button.setTextColor(active ? ACTIVE_COLOR : INACTIVE_COLOR);
			button.setAction(0, active ? "Show all bank items" : "Show farm-run items");
		}
		bankSearch.layoutBank();
	}
}

package com.farmingpatchadvisor;

import java.util.EnumSet;
import java.util.Set;

public enum ChecklistPatch
{
	ALLOTMENT(PatchType.ALLOTMENT),
	FLOWER(PatchType.FLOWER),
	HERB(PatchType.HERB),
	HOPS(PatchType.HOPS),
	BUSH(PatchType.BUSH),
	TREE(PatchType.TREE),
	FRUIT_TREE(PatchType.FRUIT_TREE),
	HARDWOOD_TREE(PatchType.HARDWOOD_TREE),
	CACTUS(PatchType.CACTUS),
	MUSHROOM(PatchType.MUSHROOM),
	BELLADONNA(PatchType.BELLADONNA),
	CALQUAT(PatchType.CALQUAT),
	SPIRIT_TREE(PatchType.SPIRIT_TREE),
	SEAWEED(PatchType.SEAWEED),
	GRAPEVINE(PatchType.GRAPEVINE),
	CELASTRUS(PatchType.CELASTRUS),
	REDWOOD(PatchType.REDWOOD),
	HESPORI(PatchType.HESPORI),
	ANIMA(PatchType.ANIMA),
	CRYSTAL_TREE(PatchType.CRYSTAL_TREE),
	CORAL(PatchType.CORAL);

	private final PatchType patchType;

	ChecklistPatch(PatchType patchType)
	{
		this.patchType = patchType;
	}

	PatchType getPatchType()
	{
		return patchType;
	}

	static Set<ChecklistPatch> selected(FarmingPatchAdvisorConfig config)
	{
		EnumSet<ChecklistPatch> selected = EnumSet.noneOf(ChecklistPatch.class);
		for (ChecklistPatch patch : values())
		{
			if (patch.isEnabled(config))
			{
				selected.add(patch);
			}
		}
		return selected;
	}

	static boolean includes(Set<ChecklistPatch> selected, PatchType patchType)
	{
		for (ChecklistPatch patch : selected)
		{
			if (patch.patchType == patchType)
			{
				return true;
			}
		}
		return false;
	}

	private boolean isEnabled(FarmingPatchAdvisorConfig config)
	{
		switch (this)
		{
			case ALLOTMENT: return config.checklistAllotment();
			case FLOWER: return config.checklistFlower();
			case HERB: return config.checklistHerb();
			case HOPS: return config.checklistHops();
			case BUSH: return config.checklistBush();
			case TREE: return config.checklistTree();
			case FRUIT_TREE: return config.checklistFruitTree();
			case HARDWOOD_TREE: return config.checklistHardwoodTree();
			case CACTUS: return config.checklistCactus();
			case MUSHROOM: return config.checklistMushroom();
			case BELLADONNA: return config.checklistBelladonna();
			case CALQUAT: return config.checklistCalquat();
			case SPIRIT_TREE: return config.checklistSpiritTree();
			case SEAWEED: return config.checklistSeaweed();
			case GRAPEVINE: return config.checklistGrapevine();
			case CELASTRUS: return config.checklistCelastrus();
			case REDWOOD: return config.checklistRedwood();
			case HESPORI: return config.checklistHespori();
			case ANIMA: return config.checklistAnima();
			case CRYSTAL_TREE: return config.checklistCrystalTree();
			case CORAL: return config.checklistCoral();
			default: return true;
		}
	}

	@Override
	public String toString()
	{
		return patchType.getDisplayName();
	}
}

package com.farmingpatchadvisor;

import java.util.EnumSet;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class FarmRunTypeTest
{
	@Test
	public void categorizesEverySupportedPatchType()
	{
		EnumSet<PatchType> categorized = EnumSet.noneOf(PatchType.class);
		for (PatchType patchType : PatchType.values())
		{
			FarmRunType.forPatchType(patchType);
			categorized.add(patchType);
		}
		assertEquals(EnumSet.allOf(PatchType.class), categorized);
	}

	@Test
	public void usesExpectedFarmRunCategories()
	{
		assertEquals(FarmRunType.ALLOTMENT_FLOWER, FarmRunType.forPatchType(PatchType.ALLOTMENT));
		assertEquals(FarmRunType.ALLOTMENT_FLOWER, FarmRunType.forPatchType(PatchType.FLOWER));
		assertEquals(FarmRunType.HERB, FarmRunType.forPatchType(PatchType.HERB));
		assertEquals(FarmRunType.FRUIT_TREE_CALQUAT, FarmRunType.forPatchType(PatchType.CALQUAT));
		assertEquals(FarmRunType.SPECIALTY, FarmRunType.forPatchType(PatchType.SEAWEED));
		assertEquals(FarmRunType.SPECIALTY, FarmRunType.forPatchType(PatchType.ANIMA));
	}

	@Test
	public void magicSecateursOnlyApplyToWikiListedYieldPatches()
	{
		assertTrue(FarmingLoadout.isYieldBoostedByMagicSecateurs(PatchType.HERB));
		assertTrue(FarmingLoadout.isYieldBoostedByMagicSecateurs(PatchType.ALLOTMENT));
		assertTrue(FarmingLoadout.isYieldBoostedByMagicSecateurs(PatchType.HOPS));
		assertTrue(FarmingLoadout.isYieldBoostedByMagicSecateurs(PatchType.GRAPEVINE));
		assertFalse(FarmingLoadout.isYieldBoostedByMagicSecateurs(PatchType.TREE));
	}

	@Test
	public void usesCorrectCareFlagsForEveryPatchType()
	{
		EnumSet<PatchType> compostAndWater = EnumSet.of(
			PatchType.ALLOTMENT,
			PatchType.FLOWER,
			PatchType.HOPS);
		EnumSet<PatchType> compostOnly = EnumSet.of(
			PatchType.HERB,
			PatchType.BUSH,
			PatchType.TREE,
			PatchType.FRUIT_TREE,
			PatchType.HARDWOOD_TREE,
			PatchType.CACTUS,
			PatchType.MUSHROOM,
			PatchType.BELLADONNA,
			PatchType.CALQUAT,
			PatchType.SPIRIT_TREE,
			PatchType.SEAWEED,
			PatchType.CELASTRUS,
			PatchType.REDWOOD,
			PatchType.CRYSTAL_TREE,
			PatchType.CORAL);
		EnumSet<PatchType> noCareFlags = EnumSet.of(
			PatchType.GRAPEVINE,
			PatchType.HESPORI,
			PatchType.ANIMA);

		EnumSet<PatchType> audited = EnumSet.noneOf(PatchType.class);
		audited.addAll(compostAndWater);
		audited.addAll(compostOnly);
		audited.addAll(noCareFlags);
		assertEquals(EnumSet.allOf(PatchType.class), audited);

		for (PatchType patchType : PatchType.values())
		{
			assertEquals(compostAndWater.contains(patchType), patchType.canBeWatered());
			assertEquals(compostAndWater.contains(patchType) || compostOnly.contains(patchType),
				patchType.usesCompost());
		}
	}
}

